import{_ as e,o as a,c as t}from"./chunks/framework.D1Ss-Xl7.js";const h=JSON.parse('{"title":"Page 3 - css | Tag","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"slug":"css/page/3","tag":"css","title":"Page 3 - css | Tag","prev":"/tags/css/page/2/","next":null,"posts":[{"title":"关于CSS解决高度自适应和宽度自适应的问题","url":"/posts/2013-03-10-css-adapt-width-and-height/","date":"2013-03-10 19:09","tags":["css"],"html":"<p>今天在做一个地图的 web 应用,这是个大坑...首先开始设计首页,于是开始山寨谷歌地图了 =.=\\n设计出来基本的 div 框架之后,想做到地图界面宽度和高度自动适应浏览器.之前做网站的需求都是固定宽度和高度的.于是我变开始折腾了.</p>\\n<h2 id=\\"自适应宽度\\" tabindex=\\"-1\\">自适应宽度 <a class=\\"header-anchor\\" href=\\"#自适应宽度\\" aria-label=\\"Permalink to &quot;自适应宽度&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>自适应宽度的难处在于网页里有超过两个并列的 div,如果两列都是变宽的话就直接按比例设置就好了,关键在于 1 列需要固定宽度另外一列需要自适应.我遇到的就是后者,具体情况是第一列需\\n要固定宽度 <code>350px</code>,第二列的宽度是 <code>100%-350px</code>,最简单的方法是设置第二列的宽度是 <code>width: -webkit-calc(100% - 350px);</code>.\\n但是这个方法的适用性不太好,由于我用的 Archlinux,也不好测试 IE 是否支持,估计是不可能支持的吧.\\n另外一个方法是设置第一个 div 的属性为 float:left;这样第一列的 div 就脱离整个文档流,第二个 div 直接设置 <code>margin-left: 350px;</code> 即可.</p>\\n<h2 id=\\"自适应高度\\" tabindex=\\"-1\\">自适应高度 <a class=\\"header-anchor\\" href=\\"#自适应高度\\" aria-label=\\"Permalink to &quot;自适应高度&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>自适应高度遇到的问题也是上面有一个固定高度为 <code>142px</code> 的 div,下面的 div 的高度为 <code>100%-142px</code>.\\n同样可以设置高度为 <code>height: -webkit-calc(100% - 142px);</code>. 另外一种方法是把 div 设置成 <code>position: absolute;</code>\\n脱离文档流,然后设置 <code>top:142px; bottom:0px;</code> 即可.</p>\\n"}]},"relativePath":"tags/css/page/3/index.md","filePath":"tags/[slug].md"}'),o={name:"tags/css/page/3/index.md"};function s(c,d,i,n,p,r){return a(),t("div")}const g=e(o,[["render",s]]);export{h as __pageData,g as default};
